 EditText typed;View connectionDot;LinearLayout root;final Handler h=new Handler();volatile boolean ready;boolean visible,connectionReady,checkOnOpen=true,checking,callPromptActive,micPromptActive,pendingListen,pendingIntentListen;String deferredAction,connectionMessage="Проверка связи…";
