 void button(String name,Runnable action){Button b=new Button(this);b.setText(name);b.setTextColor(Color.WHITE);b.setAllCaps(false);GradientDrawable background=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xcc285c85,0x99444372});background.setCornerRadius(dp(22));background.setStroke(dp(1),0x667fcef5);b.setBackground(background);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(54));lp.topMargin=dp(9);root.addView(b,lp);b.setOnClickListener(v->action.run());}
 public void onCreate(Bundle state){super.onCreate(state);applyVerificationWindow();setVolumeControlStream(android.media.AudioManager.STREAM_MUSIC);getWindow().setStatusBarColor(0xff101c32);getWindow().setNavigationBarColor(0xff101c32);ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(24),dp(20),dp(24),dp(30));root.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff101c32,0xff163f55,0xff181b32}));scroll.setFillViewport(true);scroll.addView(root);setContentView(scroll);
 LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);root.addView(header,new LinearLayout.LayoutParams(-1,dp(62)));TextView title=new TextView(this);title.setText("J A R V I S");title.setTextSize(32);title.setTextColor(Color.WHITE);title.setTypeface(null,Typeface.BOLD);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));connectionDot=new View(this);header.addView(connectionDot,new LinearLayout.LayoutParams(dp(10),dp(10)));showConnection(0xff8da3b8,"Проверка связи…");connectionDot.setOnClickListener(v->Toast.makeText(this,connectionMessage,Toast.LENGTH_LONG).show());
 button("Включить ожидание «Джарвис / Jarvis»",()->start("START"));button("Выключить микрофон и ассистента",()->{getSharedPreferences("service",0).edit().putBoolean("enabled",false).apply();stopService(new Intent(this,Assistant.class));Assistant.status="Выключен";});
 typed=new EditText(this);typed.setHint("Напишите вопрос…");typed.setTextColor(Color.WHITE);typed.setHintTextColor(0xffacbfce);typed.setMaxLines(4);root.addView(typed);button("Отправить текст",()->{String query=typed.getText().toString().trim();if(query.isEmpty())return;start("TEXT",query);typed.setText("");});button("Очистить контекст разговора",()->{Assistant.clearHistory();getSharedPreferences("dialog",0).edit().clear().apply();Assistant.last="";});pendingIntentListen=getIntent().getBooleanExtra("listen",false);
 new Thread(()->{try{Net.provision(this);runOnUiThread(()->{if(isDestroyed())return;connectionReady=true;checkWhenReady();});File en=new File(getFilesDir(),"vosk-model-small-en-us-0.15");if(!new File(en,"ready").exists()){copy("vosk-model-small-en-us-0.15",en);new File(en,"ready").createNewFile();}File ru=new File(getFilesDir(),"vosk-model-small-ru-0.22");if(!new File(ru,"ready").exists()){copy("vosk-model-small-ru-0.22",ru);new File(ru,"ready").createNewFile();}ready=true;runOnUiThread(()->{if(!isDestroyed()&&pendingIntentListen){pendingIntentListen=false;start("LISTEN");}});}catch(Exception e){Assistant.status="Подготовка: "+e.getClass().getSimpleName();runOnUiThread(()->{if(!isDestroyed())showConnection(0xffed7c83,"Не удалось подготовить приложение");});}},"JarvisPrepare").start();}
 void showConnection(int color,String message){connectionMessage=message;GradientDrawable circle=new GradientDrawable();circle.setShape(GradientDrawable.OVAL);circle.setColor(color);connectionDot.setBackground(circle);connectionDot.setContentDescription(message);}
 void checkWhenReady(){if(!connectionReady||!visible||!checkOnOpen||checking)return;checkOnOpen=false;checking=true;showConnection(0xff8da3b8,"Проверка связи…");new Thread(()->{boolean available=false,key=false;String message;try{JSONObject health=Net.call(this,"/health",null);available=health.optBoolean("ok");key=health.optBoolean("api_key_ready");message=available?(key?"Сервер доступен":"На сервере не задан ключ AI/ML API"):"Сервер не готов";}catch(Exception e){message=Net.error(e);}final boolean online=available,keyReady=key;final String detail=message;android.util.Log.i("JarvisHealth",online?(keyReady?"connected":"api_key_missing"):"failed");runOnUiThread(()->{checking=false;if(isDestroyed())return;showConnection(online?(keyReady?0xff83efc8:0xffefc87b):0xffed7c83,detail);if(visible&&checkOnOpen)checkWhenReady();});},"JarvisHealth").start();}
 void requestCallPermissionsOnce(){if(callPromptActive||micPromptActive)return;android.content.SharedPreferences prefs=getSharedPreferences("onboarding",0);if(prefs.getBoolean("call_permissions_prompted",false))return;ArrayList<String> missing=new ArrayList<>();for(String permission:new String[]{"android.permission.READ_CONTACTS","android.permission.CALL_PHONE"})if(checkSelfPermission(permission)!=PackageManager.PERMISSION_GRANTED)missing.add(permission);prefs.edit().putBoolean("call_permissions_prompted",true).apply();if(!missing.isEmpty()){callPromptActive=true;requestPermissions(missing.toArray(new String[0]),41);}}
