 protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);applyVerificationWindow();checkOnOpen=true;checkWhenReady();if(intent.getBooleanExtra("listen",false)){if(ready)start("LISTEN");else pendingIntentListen=true;}}
