 void copy(String path,File out)throws Exception{String[] names=getAssets().list(path);if(names.length>0){out.mkdirs();for(String name:names)copy(path+"/"+name,new File(out,name));}else{out.getParentFile().mkdirs();try(InputStream in=getAssets().open(path);OutputStream stream=new FileOutputStream(out)){byte[] buffer=new byte[65536];int count;while((count=in.read(buffer))>0)stream.write(buffer,0,count);}}}
 void start(String action){start(action,null);}void start(String action,String query){if(!ready){Toast.makeText(this,"Подождите подготовку модели",Toast.LENGTH_SHORT).show();return;}if(!action.equals("TEXT")&&callPromptActive){deferredAction=action;return;}if(!action.equals("TEXT")&&checkSelfPermission("android.permission.RECORD_AUDIO")!=PackageManager.PERMISSION_GRANTED){pendingListen=action.equals("LISTEN");micPromptActive=true;requestPermissions(new String[]{"android.permission.RECORD_AUDIO"},1);return;}Intent intent=new Intent(this,Assistant.class).setAction(action);if(query!=null)intent.putExtra("text",query);startForegroundService(intent);}
 public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==41){callPromptActive=false;if(deferredAction!=null){String action=deferredAction;deferredAction=null;start(action);}}else if(request==1){micPromptActive=false;if(grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED)start(pendingListen?"LISTEN":"START");requestCallPermissionsOnce();}}
